CLOSURE_CHECKS_CLASSIFIER_AUDIT: {
  "schema_version": 1,
  "migration_run_id": "2c3c43fe-7cff-4324-ad4f-4318aae71ef6",
  "snapshot_timestamp": "2026-05-22T01:27:20Z",
  "ticket_id": "f06e-56d3",
  "items": [
    {
      "original_text": "Review sub-agents at standard tier and above verify that external API calls, model names, and library function references in the diff actually exist, and flag unverifiable references as findings",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes a one-time review task with a defined completion state (findings flagged), not an ongoing system property"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    },
    {
      "original_text": "A new finding severity fragile is added that blocks merge like important, representing code that functions but won't survive change (hardcoded values that should come from an API, workarounds for missing capabilities, shims that won't survive an upgrade)",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability (a new finding severity type that persistently blocks merges) rather than a one-time task completion"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Any reviewer below opus can emit an ESCALATE_REVIEW signal for findings it's uncertain about; the orchestrator re-dispatches those findings to the next model tier (haiku to sonnet, sonnet to opus) with focused context before entering resolution",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability where reviewers persistently have the ability to escalate uncertain findings through a tiered model orchestration process"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Escalation is a one-way ratchet: once a review escalates to a higher model tier, all subsequent re-reviews for that change remain at the escalated tier or above \u2014 the review never drops back to the original lower-tier model",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system behavior governing how escalation persists across review cycles, not a one-time migration or task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Opus verdicts on escalated findings are terminal \u2014 no further escalation possible; a fragile classification from opus blocks merge",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior where Opus verdicts function as terminal decisions that prevent further escalation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The classifier bumps light to standard when the diff introduces external API calls or imports not already in the project's dependency manifest",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing system behavior/rule that the classifier applies to classify items, not a one-time task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When a reviewer detects a pattern of hallucinations or fragile fixes in the same diff, it emits an approach_viability_concern signal that the orchestrator can use to route back to implementation-plan",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability where the reviewer continuously detects patterns and emits signals for orchestrator routing"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The current deep-tier re-review escalation (pass 3+ to full deep pipeline) is replaced by the within-review ESCALATE_REVIEW mechanism",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable change to how the system handles review escalations, replacing one mechanism with another that persists as ongoing behavior"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    }
  ]
}
